export const uiAppJs = "const config = JSON.parse(document.body.dataset.config);\n\nconst dropEl = document.getElementById(\"drop\");\nconst fileEl = document.getElementById(\"file\");\nconst presetsEl = document.getElementById(\"presets\");\nconst titleEl = document.getElementById(\"title\");\nconst progressEl = document.getElementById(\"progress\");\nconst progressFill = document.getElementById(\"progress-fill\");\nconst progressLabel = document.getElementById(\"progress-label\");\nconst noticeEl = document.getElementById(\"notice\");\nconst maxEl = document.getElementById(\"max-images\");\n\nlet ttl = config.defaultTtlSeconds;\nlet uploading = false;\n\nmaxEl.textContent = String(config.maxAssets);\n\nfunction notice(message) {\n  if (!message) {\n    noticeEl.hidden = true;\n    noticeEl.textContent = \"\";\n    return;\n  }\n  noticeEl.hidden = false;\n  noticeEl.textContent = message;\n}\n\nfunction showProgress(fraction, label) {\n  progressEl.hidden = false;\n  progressFill.style.width = (Math.max(0, Math.min(1, fraction)) * 100).toFixed(1) + \"%\";\n  progressLabel.textContent = label || \"\";\n}\n\nfunction hideProgress() {\n  progressEl.hidden = true;\n  progressFill.style.width = \"0%\";\n  progressLabel.textContent = \"\";\n}\n\nfunction postBody(url, file, onProgress) {\n  return new Promise((resolve, reject) => {\n    const xhr = new XMLHttpRequest();\n    xhr.open(\"POST\", url);\n    xhr.setRequestHeader(\"content-type\", file.type || \"application/octet-stream\");\n    xhr.responseType = \"json\";\n    xhr.upload.addEventListener(\"progress\", (event) => {\n      if (event.lengthComputable) onProgress(event.loaded / event.total);\n    });\n    xhr.addEventListener(\"load\", () => resolve({ status: xhr.status, payload: xhr.response }));\n    xhr.addEventListener(\"error\", () => reject(new Error(\"network\")));\n    xhr.send(file);\n  });\n}\n\nfunction buildPresets() {\n  for (const preset of config.presets) {\n    const button = document.createElement(\"button\");\n    button.type = \"button\";\n    button.className = \"preset\";\n    button.textContent = preset.label;\n    button.dataset.seconds = String(preset.seconds);\n    button.setAttribute(\"aria-pressed\", String(preset.seconds === ttl));\n    button.addEventListener(\"click\", () => {\n      if (uploading) return;\n      ttl = preset.seconds;\n      for (const other of presetsEl.children) {\n        other.setAttribute(\"aria-pressed\", String(other === button));\n      }\n    });\n    presetsEl.append(button);\n  }\n}\n\nasync function uploadBatch(files) {\n  const totalBytes = files.reduce((sum, file) => sum + file.size, 0) || 1;\n\n  uploading = true;\n  dropEl.classList.add(\"busy\");\n  showProgress(0, \"Uploading 1 of \" + files.length + \"…\");\n\n  let shareId = null;\n  let doneBytes = 0;\n  let error = \"\";\n\n  for (let index = 0; index < files.length; index += 1) {\n    const file = files[index];\n    const creating = !shareId;\n\n    const params = new URLSearchParams();\n    params.set(\"filename\", file.name);\n    if (creating) {\n      params.set(\"ttl\", String(ttl));\n      const title = titleEl.value.trim();\n      if (title) params.set(\"title\", title);\n    }\n\n    const url =\n      (creating ? \"/api/upload\" : \"/api/posts/\" + shareId + \"/assets\") + \"?\" + params.toString();\n\n    try {\n      const { status, payload } = await postBody(url, file, (fraction) => {\n        showProgress(\n          (doneBytes + fraction * file.size) / totalBytes,\n          \"Uploading \" + (index + 1) + \" of \" + files.length + \"…\",\n        );\n      });\n\n      if (status < 200 || status >= 300 || !payload) {\n        error = (payload && payload.error) || \"Upload failed (\" + status + \").\";\n        break;\n      }\n\n      if (creating) shareId = payload.id;\n      doneBytes += file.size;\n    } catch {\n      error = \"Network error while uploading.\";\n      break;\n    }\n  }\n\n  uploading = false;\n  dropEl.classList.remove(\"busy\");\n  hideProgress();\n\n  if (shareId) {\n    // The manage page owns reordering, deletions and further uploads.\n    location.href = \"/m/\" + shareId;\n    return;\n  }\n\n  notice(error || \"Upload failed.\");\n}\n\nfunction handleFiles(fileList) {\n  notice(\"\");\n  if (uploading) {\n    notice(\"Still uploading — wait a moment.\");\n    return;\n  }\n\n  const incoming = [];\n  for (const file of fileList) {\n    if (file.size === 0) {\n      notice(file.name + \" is empty.\");\n      continue;\n    }\n    if (file.size > config.maxUploadBytes) {\n      notice(file.name + \" is too large (max \" + humanBytes(config.maxUploadBytes) + \").\");\n      continue;\n    }\n    incoming.push(file);\n  }\n\n  if (incoming.length === 0) return;\n\n  if (incoming.length > config.maxAssets) {\n    notice(\"Only \" + config.maxAssets + \" files fit in a share.\");\n    incoming.length = config.maxAssets;\n  }\n\n  uploadBatch(incoming);\n}\n\nfunction humanBytes(bytes) {\n  if (bytes < 1024) return bytes + \" B\";\n  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + \" KB\";\n  return (bytes / (1024 * 1024)).toFixed(2) + \" MB\";\n}\n\ndropEl.addEventListener(\"click\", () => {\n  if (!uploading) fileEl.click();\n});\n\ndropEl.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Enter\" || event.key === \" \") {\n    event.preventDefault();\n    if (!uploading) fileEl.click();\n  }\n});\n\nfileEl.addEventListener(\"change\", () => {\n  if (fileEl.files) handleFiles(fileEl.files);\n  fileEl.value = \"\";\n});\n\nfor (const type of [\"dragenter\", \"dragover\"]) {\n  dropEl.addEventListener(type, (event) => {\n    event.preventDefault();\n    dropEl.classList.add(\"active\");\n  });\n}\n\nfor (const type of [\"dragleave\", \"drop\"]) {\n  dropEl.addEventListener(type, (event) => {\n    event.preventDefault();\n    dropEl.classList.remove(\"active\");\n  });\n}\n\ndropEl.addEventListener(\"drop\", (event) => {\n  const files = event.dataTransfer && event.dataTransfer.files;\n  if (files) handleFiles(files);\n});\n\ndocument.addEventListener(\"paste\", (event) => {\n  const items = event.clipboardData && event.clipboardData.items;\n  if (!items) return;\n\n  const pasted = [];\n  for (const item of items) {\n    if (item.kind === \"file\") {\n      const file = item.getAsFile();\n      if (file) pasted.push(file);\n    }\n  }\n\n  if (pasted.length) {\n    event.preventDefault();\n    handleFiles(pasted);\n  }\n});\n\nbuildPresets();\n";

export const uiViewJs = "// Countdown for the share header.\nfor (const element of document.querySelectorAll(\"[data-expires-at]\")) {\n  const expiresAt = Number(element.getAttribute(\"data-expires-at\"));\n\n  const tick = () => {\n    const remaining = expiresAt - Date.now();\n    if (remaining <= 0) {\n      element.textContent = \"expired\";\n      element.classList.add(\"expired\");\n      clearInterval(timer);\n      location.reload();\n      return;\n    }\n\n    const seconds = Math.floor(remaining / 1000);\n    const days = Math.floor(seconds / 86400);\n    const hours = Math.floor((seconds % 86400) / 3600);\n    const minutes = Math.floor((seconds % 3600) / 60);\n    const secs = seconds % 60;\n\n    if (days > 0) element.textContent = days + \"d \" + hours + \"h\";\n    else if (hours > 0) element.textContent = hours + \"h \" + minutes + \"m\";\n    else if (minutes > 0) element.textContent = minutes + \"m \" + secs + \"s\";\n    else element.textContent = secs + \"s\";\n  };\n\n  tick();\n  const timer = setInterval(tick, 1000);\n}\n\nconst thumbs = [...document.querySelectorAll(\".thumb\")];\n\nif (thumbs.length > 0) {\n  const box = document.createElement(\"div\");\n  box.className = \"lightbox\";\n  box.setAttribute(\"role\", \"dialog\");\n  box.setAttribute(\"aria-modal\", \"true\");\n  box.setAttribute(\"aria-label\", \"Image viewer\");\n  box.innerHTML =\n    '<button type=\"button\" class=\"lightbox-close\" aria-label=\"Close\">×</button>' +\n    '<button type=\"button\" class=\"lightbox-prev\" aria-label=\"Previous\">‹</button>' +\n    '<button type=\"button\" class=\"lightbox-next\" aria-label=\"Next\">›</button>' +\n    '<div class=\"lightbox-viewport\"><div class=\"lightbox-track\"></div></div>' +\n    '<div class=\"lightbox-dots\"></div>';\n  document.body.append(box);\n\n  const track = box.querySelector(\".lightbox-track\");\n  const dots = box.querySelector(\".lightbox-dots\");\n  const prevButton = box.querySelector(\".lightbox-prev\");\n  const nextButton = box.querySelector(\".lightbox-next\");\n  const closeButton = box.querySelector(\".lightbox-close\");\n\n  const images = thumbs.map((thumb) => {\n    const slide = document.createElement(\"div\");\n    slide.className = \"lightbox-slide\";\n\n    const image = document.createElement(\"img\");\n    image.alt = thumb.dataset.name || \"\";\n    image.decoding = \"async\";\n    image.loading = \"lazy\";\n    image.draggable = false;\n\n    slide.append(image);\n    track.append(slide);\n    return image;\n  });\n\n  const dotsList = thumbs.map((_, dotIndex) => {\n    const dot = document.createElement(\"button\");\n    dot.type = \"button\";\n    dot.className = \"lightbox-dot\";\n    dot.setAttribute(\"aria-label\", \"Image \" + (dotIndex + 1));\n    dot.addEventListener(\"click\", (event) => {\n      event.stopPropagation();\n      jump(dotIndex);\n    });\n    dots.append(dot);\n    return dot;\n  });\n\n  let index = 0;\n  let dragging = false;\n  let swiped = false;\n  let startX = 0;\n  let startY = 0;\n  let dragX = 0;\n  let dragY = 0;\n\n  const isOpen = () => box.classList.contains(\"open\");\n\n  function ensure(dotIndex) {\n    if (dotIndex < 0 || dotIndex >= thumbs.length) return;\n    if (!images[dotIndex].src) {\n      images[dotIndex].src = thumbs[dotIndex].dataset.full;\n    }\n  }\n\n  function render() {\n    track.style.transform = \"translateX(\" + -index * 100 + \"%)\";\n    dotsList.forEach((dot, dotIndex) => {\n      dot.classList.toggle(\"active\", dotIndex === index);\n    });\n    prevButton.hidden = index === 0;\n    nextButton.hidden = index === thumbs.length - 1;\n  }\n\n  function open(nextIndex) {\n    index = nextIndex;\n    swiped = false;\n\n    ensure(index);\n    ensure(index + 1);\n    ensure(index - 1);\n\n    track.style.transition = \"none\";\n    render();\n    void track.offsetWidth;\n\n    box.classList.add(\"open\");\n    document.body.classList.add(\"lightbox-open\");\n  }\n\n  function close() {\n    if (!isOpen()) return;\n    box.classList.remove(\"open\");\n    document.body.classList.remove(\"lightbox-open\");\n  }\n\n  function go(direction, wrap) {\n    let nextIndex = index + direction;\n\n    if (wrap) {\n      nextIndex = (nextIndex + thumbs.length) % thumbs.length;\n    } else if (nextIndex < 0 || nextIndex >= thumbs.length) {\n      return;\n    }\n\n    index = nextIndex;\n    ensure(index);\n    ensure(index + 1);\n    ensure(index - 1);\n\n    track.style.transition = \"transform 0.3s ease\";\n    render();\n  }\n\n  function jump(nextIndex) {\n    index = nextIndex;\n    ensure(index);\n    ensure(index + 1);\n    ensure(index - 1);\n    track.style.transition = \"transform 0.3s ease\";\n    render();\n  }\n\n  thumbs.forEach((thumb, thumbIndex) => {\n    thumb.addEventListener(\"click\", (event) => {\n      if (event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) return;\n      event.preventDefault();\n      open(thumbIndex);\n    });\n  });\n\n  closeButton.addEventListener(\"click\", (event) => {\n    event.stopPropagation();\n    close();\n  });\n\n  prevButton.addEventListener(\"click\", (event) => {\n    event.stopPropagation();\n    go(-1, false);\n  });\n\n  nextButton.addEventListener(\"click\", (event) => {\n    event.stopPropagation();\n    go(1, false);\n  });\n\n  // Clicking anywhere dismisses.\n  box.addEventListener(\"click\", (event) => {\n    event.preventDefault();\n    if (swiped) return;\n    close();\n  });\n\n  document.addEventListener(\"keydown\", (event) => {\n    if (!isOpen()) return;\n    if (event.key === \"Escape\") {\n      event.preventDefault();\n      close();\n    } else if (event.key === \"ArrowLeft\") {\n      event.preventDefault();\n      go(-1, true);\n    } else if (event.key === \"ArrowRight\") {\n      event.preventDefault();\n      go(1, true);\n    }\n  });\n\n  function trackTransform() {\n    return \"translateX(calc(\" + -index * 100 + \"% + \" + dragX + \"px))\";\n  }\n\n  box.addEventListener(\n    \"touchstart\",\n    (event) => {\n      if (event.touches.length !== 1) return;\n      dragging = true;\n      swiped = false;\n      dragX = 0;\n      dragY = 0;\n      startX = event.touches[0].clientX;\n      startY = event.touches[0].clientY;\n      track.style.transition = \"none\";\n    },\n    { passive: true },\n  );\n\n  box.addEventListener(\n    \"touchmove\",\n    (event) => {\n      if (!dragging || event.touches.length !== 1) return;\n      dragX = event.touches[0].clientX - startX;\n      dragY = event.touches[0].clientY - startY;\n      track.style.transform = trackTransform();\n    },\n    { passive: true },\n  );\n\n  box.addEventListener(\n    \"touchend\",\n    () => {\n      if (!dragging) return;\n      dragging = false;\n\n      if (dragY > 100) {\n        close();\n        return;\n      }\n\n      if (Math.abs(dragX) > 50) {\n        swiped = true;\n        go(dragX < 0 ? 1 : -1, false);\n        window.setTimeout(() => {\n          swiped = false;\n        }, 350);\n      } else {\n        track.style.transition = \"transform 0.2s ease\";\n        render();\n      }\n\n      dragX = 0;\n      dragY = 0;\n    },\n    { passive: true },\n  );\n}\n";

export const uiManageJs = "const shareId = document.body.dataset.share;\n\nconst list = document.getElementById(\"assets\");\nconst titleEl = document.getElementById(\"title\");\nconst saveTitleBtn = document.getElementById(\"save-title\");\nconst shareUrlEl = document.getElementById(\"post-url\");\nconst copyBtn = document.getElementById(\"copy-link\");\nconst addBtn = document.getElementById(\"add\");\nconst addInput = document.getElementById(\"add-input\");\nconst deleteShareBtn = document.getElementById(\"delete-share\");\nconst progressEl = document.getElementById(\"progress\");\nconst progressFill = document.getElementById(\"progress-fill\");\nconst progressLabel = document.getElementById(\"progress-label\");\nconst noticeEl = document.getElementById(\"notice\");\n\nfunction notice(message) {\n  if (!message) {\n    noticeEl.hidden = true;\n    noticeEl.textContent = \"\";\n    return;\n  }\n  noticeEl.hidden = false;\n  noticeEl.textContent = message;\n}\n\nfunction showProgress(fraction, label) {\n  progressEl.hidden = false;\n  progressFill.style.width = (Math.max(0, Math.min(1, fraction)) * 100).toFixed(1) + \"%\";\n  progressLabel.textContent = label || \"\";\n}\n\nfunction hideProgress() {\n  progressEl.hidden = true;\n  progressFill.style.width = \"0%\";\n  progressLabel.textContent = \"\";\n}\n\nfunction humanBytes(bytes) {\n  if (bytes < 1024) return bytes + \" B\";\n  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + \" KB\";\n  return (bytes / (1024 * 1024)).toFixed(2) + \" MB\";\n}\n\nfunction postBody(url, file, onProgress) {\n  return new Promise((resolve, reject) => {\n    const xhr = new XMLHttpRequest();\n    xhr.open(\"POST\", url);\n    xhr.setRequestHeader(\"content-type\", file.type || \"application/octet-stream\");\n    xhr.responseType = \"json\";\n    xhr.upload.addEventListener(\"progress\", (event) => {\n      if (event.lengthComputable) onProgress(event.loaded / event.total);\n    });\n    xhr.addEventListener(\"load\", () => resolve({ status: xhr.status, payload: xhr.response }));\n    xhr.addEventListener(\"error\", () => reject(new Error(\"network\")));\n    xhr.send(file);\n  });\n}\n\nfunction assetIds() {\n  return [...list.children].map((item) => item.dataset.id);\n}\n\nasync function saveOrder() {\n  try {\n    const response = await fetch(\"/api/posts/\" + shareId + \"/order\", {\n      method: \"PATCH\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ assetIds: assetIds() }),\n    });\n    if (!response.ok) notice(\"Could not save the new order.\");\n    else notice(\"\");\n  } catch {\n    notice(\"Could not save the new order.\");\n  }\n}\n\nlet dragging = null;\n\nlist.addEventListener(\"dragstart\", (event) => {\n  const item = event.target.closest(\".manage-item\");\n  if (!item) return;\n  dragging = item;\n  item.classList.add(\"dragging\");\n  event.dataTransfer.effectAllowed = \"move\";\n  event.dataTransfer.setData(\"text/plain\", item.dataset.id);\n});\n\nlist.addEventListener(\"dragend\", () => {\n  if (dragging) dragging.classList.remove(\"dragging\");\n  dragging = null;\n});\n\nlist.addEventListener(\"dragover\", (event) => {\n  if (!dragging) return;\n  event.preventDefault();\n\n  const target = event.target.closest(\".manage-item\");\n  if (!target || target === dragging) return;\n\n  const rect = target.getBoundingClientRect();\n  const sameRow = event.clientY >= rect.top && event.clientY <= rect.bottom;\n  const after = sameRow\n    ? event.clientX > rect.left + rect.width / 2\n    : event.clientY > rect.top + rect.height / 2;\n\n  if (after) target.after(dragging);\n  else target.before(dragging);\n});\n\nlist.addEventListener(\"drop\", (event) => {\n  event.preventDefault();\n  if (dragging) saveOrder();\n});\n\nlist.addEventListener(\"click\", async (event) => {\n  const button = event.target.closest(\"button\");\n  if (!button) return;\n\n  const item = button.closest(\".manage-item\");\n  if (!item) return;\n\n  const move = button.dataset.move;\n  if (move) {\n    const delta = Number(move);\n    if (delta < 0 && item.previousElementSibling) {\n      item.previousElementSibling.before(item);\n    } else if (delta > 0 && item.nextElementSibling) {\n      item.nextElementSibling.after(item);\n    }\n    await saveOrder();\n    return;\n  }\n\n  if (button.hasAttribute(\"data-delete\")) {\n    if (!confirm(\"Delete this file from the share?\")) return;\n\n    button.disabled = true;\n    try {\n      const response = await fetch(\n        \"/api/posts/\" + shareId + \"/assets/\" + item.dataset.id,\n        { method: \"DELETE\" },\n      );\n      if (response.ok) {\n        item.remove();\n        if (list.children.length === 0) location.reload();\n      } else {\n        button.disabled = false;\n        notice(\"Could not delete that file.\");\n      }\n    } catch {\n      button.disabled = false;\n      notice(\"Could not delete that file.\");\n    }\n  }\n});\n\nsaveTitleBtn.addEventListener(\"click\", async () => {\n  saveTitleBtn.disabled = true;\n  try {\n    const response = await fetch(\"/api/posts/\" + shareId, {\n      method: \"PATCH\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ title: titleEl.value.trim() }),\n    });\n    if (!response.ok) {\n      notice(\"Could not save the title.\");\n    } else {\n      saveTitleBtn.textContent = \"Saved\";\n      setTimeout(() => {\n        saveTitleBtn.textContent = \"Save\";\n      }, 1200);\n    }\n  } catch {\n    notice(\"Could not save the title.\");\n  } finally {\n    saveTitleBtn.disabled = false;\n  }\n});\n\ncopyBtn.addEventListener(\"click\", async () => {\n  try {\n    await navigator.clipboard.writeText(shareUrlEl.value);\n    copyBtn.textContent = \"Copied\";\n    setTimeout(() => {\n      copyBtn.textContent = \"Copy\";\n    }, 1200);\n  } catch {\n    shareUrlEl.select();\n    document.execCommand(\"copy\");\n  }\n});\n\naddBtn.addEventListener(\"click\", () => addInput.click());\n\naddInput.addEventListener(\"change\", async () => {\n  const files = [...(addInput.files || [])];\n  addInput.value = \"\";\n  if (files.length === 0) return;\n\n  const total = files.reduce((sum, file) => sum + file.size, 0) || 1;\n  let done = 0;\n  let failed = false;\n\n  addBtn.disabled = true;\n  showProgress(0, \"Uploading 1 of \" + files.length + \"…\");\n\n  for (let index = 0; index < files.length; index += 1) {\n    const file = files[index];\n    const params = new URLSearchParams();\n    params.set(\"filename\", file.name);\n\n    try {\n      const { status, payload } = await postBody(\n        \"/api/posts/\" + shareId + \"/assets?\" + params.toString(),\n        file,\n        (fraction) =>\n          showProgress(\n            (done + fraction * file.size) / total,\n            \"Uploading \" + (index + 1) + \" of \" + files.length + \"…\",\n          ),\n      );\n\n      if (status >= 200 && status < 300) {\n        done += file.size;\n      } else {\n        notice((payload && payload.error) || \"Upload failed (\" + status + \").\");\n        failed = true;\n        break;\n      }\n    } catch {\n      notice(\"Network error while uploading.\");\n      failed = true;\n      break;\n    }\n  }\n\n  addBtn.disabled = false;\n  hideProgress();\n\n  if (!failed) location.reload();\n});\n\ndeleteShareBtn.addEventListener(\"click\", async () => {\n  if (!confirm(\"Delete this share and everything in it?\")) return;\n\n  deleteShareBtn.disabled = true;\n  try {\n    const response = await fetch(\"/api/posts/\" + shareId, { method: \"DELETE\" });\n    if (response.ok) {\n      location.href = \"/upload\";\n      return;\n    }\n    notice(\"Could not delete this share.\");\n  } catch {\n    notice(\"Could not delete this share.\");\n  }\n  deleteShareBtn.disabled = false;\n});\n\n// Keep the size labels honest without a page reload after deletions.\nfunction refreshCounts() {\n  const count = list.children.length;\n  if (count === 0) return;\n}\n\nrefreshCounts();\n";

